function getAllCategories() {
  return [...new Set(TCAS_DATA.programs.map(p => p.category))];
}

// Calculate recommendation score for a program based on student data
function calculateMatchScore(program, studentData) {
  let score = 0;
  let maxScore = 0;
  let details = [];
  let issues = [];

  const scores = studentData.scores || {};
  const gpa = parseFloat(studentData.gpa?.cumulative) || 0;
  const portfolio = studentData.portfolio || {};

  // GPA Check
  const minGPA = parseFloat(program.minGPA) || 0;
  if (gpa > 0) {
    if (minGPA === 0 || gpa >= minGPA) {
      score += 20;
      if (minGPA > 0) details.push(`GPA ${gpa.toFixed(2)} ✓ (ต้องการ ${minGPA})`);
    } else {
      score += Math.max(0, 20 * (gpa / minGPA));
      issues.push(`GPA ${gpa.toFixed(2)} ต่ำกว่าเกณฑ์ (ต้องการ ${minGPA})`);
    }
    maxScore += 20;
  }

  // Test Score Check (use round 3 criteria as baseline)
  const criteria = program.criteria?.round3 || {};
  let totalWeight = Object.values(criteria).reduce((a, b) => a + b, 0);

  for (const [testKey, weight] of Object.entries(criteria)) {
    const testInfo = getTestInfo(testKey);
    if (!testInfo) continue;

    const maxTestScore = testInfo.maxScore;
    const studentScore = parseFloat(scores[testKey]) || 0;

    if (studentScore > 0) {
      const pct = studentScore / maxTestScore;
      score += pct * weight;
      details.push(`${testInfo.name}: ${studentScore}/${maxTestScore} (${Math.round(pct * 100)}%)`);
    } else {
      // Test not taken
      issues.push(`ยังไม่มีคะแนน ${testInfo.name}`);
    }
    maxScore += weight;
  }

  const matchPercent = maxScore > 0 ? Math.round((score / maxScore) * 100) : 0;

  // Portfolio bonus
  const awards = portfolio.awards || [];
  const nationalAwards = awards.filter(a => a.level === 'national' || a.level === 'international').length;
  const portfolioBonus = Math.min(nationalAwards * 5, 15);

  return {
    score: Math.min(100, matchPercent + portfolioBonus),
    matchPercent,
    details,
    issues,
    portfolioBonus
  };
}

function getTestInfo(testKey) {
  for (const category of Object.values(TCAS_DATA.tests)) {
    if (category.subjects[testKey]) {
      return category.subjects[testKey];
    }
  }
  return null;
}

// ============================================================
// TCAS69 Round 3 — Category-based score criteria (อ้างอิงเกณฑ์ทั่วไป TCAS69)
// weights sum to 100 per category; keys match TCAS_DATA.tests subjects
// ============================================================
const TCAS_CATEGORY_CRITERIA = {
  'วิศวกรรม':     { tgat1:10, tgat2:20, tpat3:30, amath1:20, aphy:10, achem:10 },
  'วิทยาศาสตร์':  { tgat2:20, amath1:30, achem:20, abio:15, aphy:15 },
  'สาธารณสุข':    { tgat1:20, tgat2:20, achem:20, abio:20, ascience:20 },
  'บริหาร':       { tgat1:30, tgat2:30, amath1:20, asocial:20 },
  'มนุษยศาสตร์':  { tgat1:40, tgat2:20, athai:20, asocial:20 },
  'ครุศาสตร์':    { tgat1:20, tgat2:20, tpat5:40, asocial:20 },
  'สถาปัตยกรรม': { tpat4:40, tgat1:20, tgat2:20, amath1:20 },
  'ศิลปะ':        { tpat2:50, tgat1:30, tgat3:20 },
  'เกษตร':        { tgat2:20, amath1:20, achem:20, abio:20, ascience:20 },
  'เทคโนโลยี':   { tgat2:30, tpat3:20, amath1:30, ascience:20 },
};

const SCORE_MAX = {
  tgat1:100, tgat2:100, tgat3:100,
  tpat1:300, tpat2:100, tpat3:100, tpat4:100, tpat5:100,
  amath1:100, amath2:100, ascience:100, asocial:100, athai:100, aeng:100,
  aphy:100, achem:100, abio:100, ahist:100, afre:100, ager:100,
  ajpn:100, achn:100, akor:100,
};

const SCORE_LABEL = {
  tgat1:'TGAT1', tgat2:'TGAT2', tgat3:'TGAT3',
  tpat1:'TPAT1', tpat2:'TPAT2', tpat3:'TPAT3', tpat4:'TPAT4', tpat5:'TPAT5',
  amath1:'A-Level คณิต 1', amath2:'A-Level คณิต 2', ascience:'A-Level วิทย์',
  asocial:'A-Level สังคม', athai:'A-Level ภาษาไทย', aeng:'A-Level อังกฤษ',
  aphy:'A-Level ฟิสิกส์', achem:'A-Level เคมี', abio:'A-Level ชีววิทยา',
  ahist:'A-Level ประวัติ', afre:'A-Level ฝรั่งเศส', ager:'A-Level เยอรมัน',
  ajpn:'A-Level ญี่ปุ่น', achn:'A-Level จีน', akor:'A-Level เกาหลี',
};

// Returns:
//   { complete:true, score:number }            — all required subjects entered
//   { complete:false, score:null,
//     partialKnown:number, takenWeight:number,
//     missingSubjects:[{subj,label,weight,max}],
//     totalWeight:number }                     — some subjects missing
//   { complete:false, score:null, noData:true } — no scores at all
function calculateWeightedScore(program, studentScores) {
  const criteria = TCAS_CATEGORY_CRITERIA[program.category] || {};
  const entries  = Object.entries(criteria);
  if (entries.length === 0) return { complete: false, score: null, noData: true };

  let weightedSum  = 0;
  let takenWeight  = 0;
  let missingSubjs = [];

  for (const [subj, weight] of entries) {
    const raw = parseFloat(studentScores[subj]);
    const max = SCORE_MAX[subj] || 100;
    if (!isNaN(raw) && raw > 0) {
      weightedSum += (raw / max) * weight;
      takenWeight += weight;
    } else {
      missingSubjs.push({ subj, label: SCORE_LABEL[subj] || subj, weight, max });
    }
  }

  const totalWeight = entries.reduce((s, [, w]) => s + w, 0);

  if (missingSubjs.length === 0) {
    return { complete: true, score: weightedSum };
  }
  if (takenWeight === 0) {
    return { complete: false, score: null, noData: true };
  }
  return { complete: false, score: null, partialKnown: weightedSum, takenWeight, missingSubjs, totalWeight, criteria };
}

// Given a partial result and the historical cutoff, compute what uniform %
// across all missing subjects would be needed to reach the cutoff.
// Returns { possible:bool, requiredPct:number, perSubject:[{label,requiredPct}] }
function calcPartialRequirement(partialResult, cutoff) {
  const { partialKnown, missingSubjs, totalWeight } = partialResult;
  const remainingWeight = missingSubjs.reduce((s, m) => s + m.weight, 0);
  const stillNeeded     = cutoff - partialKnown;

  if (stillNeeded <= 0) return { possible: true, requiredPct: 0, alreadySufficient: true };

  const uniformPct = (stillNeeded / remainingWeight) * 100;
  const possible   = uniformPct <= 100;

  // Per-subject breakdown (uniform assumption)
  const perSubject = missingSubjs.map(m => ({
    label:       m.label,
    requiredPct: Math.min(100, Math.max(0, uniformPct)),
  }));

  return { possible, requiredPct: uniformPct, perSubject };
}

// 5-tier probability assessment based on score vs historical cutoff
function getAssessmentTier(studentScore, cutoff) {
  const ratio = studentScore / cutoff;
  if (ratio >= 1.15) return { tier:1, label:'โอกาสสูงมาก',   color:'#059669', bg:'#D1FAE5', textColor:'#065F46' };
  if (ratio >= 1.05) return { tier:2, label:'โอกาสสูง',      color:'#16A34A', bg:'#DCFCE7', textColor:'#14532D' };
  if (ratio >= 0.97) return { tier:3, label:'โอกาสปานกลาง', color:'#D97706', bg:'#FEF3C7', textColor:'#92400E' };
  if (ratio >= 0.88) return { tier:4, label:'โอกาสต่ำ',      color:'#EA580C', bg:'#FFEDD5', textColor:'#7C2D12' };
  return                     { tier:5, label:'โอกาสต่ำมาก',  color:'#DC2626', bg:'#FEE2E2', textColor:'#7F1D1D' };
}

// Find fallback recommendations — 2-tier priority, only good-chance programs.
//
// Priority 1: same category (field) + different university
//   → prefer same faculty name first, then sort by pass probability desc
// Priority 2: same university + same faculty + different program (different major)
//   → sort by pass probability desc
//
// Only programs where student has tier 1-3 chance (ratio >= 0.88) are included.
function getFallbackRecommendations(selectedIds, studentScores, count) {
  if (count <= 0) return [];

  const selectedSet  = new Set(selectedIds);
  const selectedProgs = TCAS_DATA.programs.filter(p => selectedSet.has(p.id));
  const selectedCats = new Set(selectedProgs.map(p => p.category));
  const selectedUnis = new Set(selectedProgs.map(p => p.universityId));
  const selectedFacs = new Set(selectedProgs.map(p => p.faculty));

  function scoreCandidate(p) {
    const hist = TCAS_HISTORICAL_STATS[p.id];
    if (!hist) return null;
    const lastY   = Object.keys(hist).sort().pop();
    const cutoff  = hist[lastY].min;
    const ws      = calculateWeightedScore(p, studentScores);
    const sPct    = ws.complete ? ws.score : (ws.partialKnown || 0);
    const ratio   = cutoff > 0 ? sPct / cutoff : 0;
    return { program: p, ratio };
  }

  // Tier 1–3: ratio >= 0.97 (โอกาสสูงมาก / สูง / ปานกลาง — excludes tier 4-5)
  const hasGoodChance = s => s && s.ratio >= 0.97;

  const used = new Set(selectedIds);
  const results = [];

  // ── Priority 1: same category, different university ──────────────────────
  const p1 = TCAS_DATA.programs
    .filter(p =>
      !used.has(p.id) &&
      selectedCats.has(p.category) &&
      !selectedUnis.has(p.universityId) &&
      TCAS_HISTORICAL_STATS[p.id]
    )
    .map(scoreCandidate)
    .filter(hasGoodChance);

  // Same faculty name first, then by descending ratio
  p1.sort((a, b) => {
    const af = selectedFacs.has(a.program.faculty) ? 0 : 1;
    const bf = selectedFacs.has(b.program.faculty) ? 0 : 1;
    return af !== bf ? af - bf : b.ratio - a.ratio;
  });

  for (const s of p1) {
    if (results.length >= count) break;
    results.push(s.program);
    used.add(s.program.id);
  }

  // ── Priority 2: same university + same faculty, different program ─────────
  if (results.length < count) {
    const p2 = TCAS_DATA.programs
      .filter(p =>
        !used.has(p.id) &&
        selectedUnis.has(p.universityId) &&
        selectedFacs.has(p.faculty) &&
        TCAS_HISTORICAL_STATS[p.id]
      )
      .map(scoreCandidate)
      .filter(hasGoodChance);

    p2.sort((a, b) => b.ratio - a.ratio);

    for (const s of p2) {
      if (results.length >= count) break;
      results.push(s.program);
      used.add(s.program.id);
    }
  }

  return results;
}

// Extra recommendations beyond the initial 10 — same priority rules as
// getFallbackRecommendations but draws from the remaining pool (not shown yet).
// minRatio = 0.97 → only tier 1-3 (สูงมาก / สูง / ปานกลาง)
function getExtraRecommendations(shownIds, selectedProgsContext, studentScores) {
  const excluded    = new Set(shownIds);
  const selectedCats = new Set(selectedProgsContext.map(p => p.category));
  const selectedUnis = new Set(selectedProgsContext.map(p => p.universityId));
  const selectedFacs = new Set(selectedProgsContext.map(p => p.faculty));
  const MIN_RATIO   = 0.97;

  function sc(p) {
    const hist = TCAS_HISTORICAL_STATS[p.id];
    if (!hist) return null;
    const lastY  = Object.keys(hist).sort().pop();
    const cutoff = hist[lastY].min;
    const ws     = calculateWeightedScore(p, studentScores);
    const sPct   = ws.complete ? ws.score : (ws.partialKnown || 0);
    return { program: p, ratio: cutoff > 0 ? sPct / cutoff : 0 };
  }

  const ok = s => s && s.ratio >= MIN_RATIO;
  const used = new Set(shownIds);
  const results = [];

  // Priority 1: same category, different university
  const p1 = TCAS_DATA.programs
    .filter(p => !used.has(p.id) && selectedCats.has(p.category) && !selectedUnis.has(p.universityId) && TCAS_HISTORICAL_STATS[p.id])
    .map(sc).filter(ok);
  p1.sort((a, b) => {
    const af = selectedFacs.has(a.program.faculty) ? 0 : 1;
    const bf = selectedFacs.has(b.program.faculty) ? 0 : 1;
    return af !== bf ? af - bf : b.ratio - a.ratio;
  });
  for (const s of p1) { results.push(s.program); used.add(s.program.id); }

  // Priority 2: same university + same faculty, different program
  const p2 = TCAS_DATA.programs
    .filter(p => !used.has(p.id) && selectedUnis.has(p.universityId) && selectedFacs.has(p.faculty) && TCAS_HISTORICAL_STATS[p.id])
    .map(sc).filter(ok);
  p2.sort((a, b) => b.ratio - a.ratio);
  for (const s of p2) { results.push(s.program); used.add(s.program.id); }

  return results;
}

// Fallback programs for GPA-based rounds (1 = Portfolio, 2 = Quota).
// Priority 1: same category, different university, GPA OK.
// Priority 2: same university + same faculty, different program, GPA OK.
// Sorted by GPA margin (largest margin first = most comfortable).
function getGpaRoundFallbacks(excludedIds, selectedProgsCtx, gpa, roundNum, count) {
  if (count <= 0) return [];
  const excluded    = new Set(excludedIds);
  const selectedCats = new Set(selectedProgsCtx.map(p => p.category));
  const selectedUnis = new Set(selectedProgsCtx.map(p => p.universityId));
  const selectedFacs = new Set(selectedProgsCtx.map(p => p.faculty));
  const gpaOk = p => gpa >= (parseFloat(p.minGPA) || 0);
  const margin = p => gpa - (parseFloat(p.minGPA) || 0);
  const used = new Set(excludedIds);
  const results = [];

  const p1 = TCAS_DATA.programs
    .filter(p => !used.has(p.id) && p.rounds.includes(roundNum) && selectedCats.has(p.category) && !selectedUnis.has(p.universityId) && gpaOk(p))
    .sort((a, b) => {
      const af = selectedFacs.has(a.faculty) ? 0 : 1;
      const bf = selectedFacs.has(b.faculty) ? 0 : 1;
      return af !== bf ? af - bf : margin(b) - margin(a);
    });
  for (const p of p1) { if (results.length >= count) break; results.push(p); used.add(p.id); }

  if (results.length < count) {
    const p2 = TCAS_DATA.programs
      .filter(p => !used.has(p.id) && p.rounds.includes(roundNum) && selectedUnis.has(p.universityId) && selectedFacs.has(p.faculty) && gpaOk(p))
      .sort((a, b) => margin(b) - margin(a));
    for (const p of p2) { if (results.length >= count) break; results.push(p); used.add(p.id); }
  }
  return results;
}

// Build sparkline SVG string for a program's historical min/max data.
// studentScore: number | null
function buildSparklineSVG(programId, studentScore, color) {
  const W = 260, H = 64;
  const PAD = { t:10, r:30, b:18, l:28 };
  const iW = W - PAD.l - PAD.r;
  const iH = H - PAD.t - PAD.b;

  const hist = TCAS_HISTORICAL_STATS[programId];
  if (!hist) return '';

  const years = Object.keys(hist).sort();
  const pts   = years.map(y => ({ year: y.slice(-2), min: hist[y].min, max: hist[y].max }));
  const n     = pts.length;
  if (n < 2) return '';

  const allV  = pts.flatMap(p => [p.min, p.max]).concat(studentScore != null ? [studentScore] : []);
  const rawMin = Math.min(...allV), rawMax = Math.max(...allV);
  const pad    = (rawMax - rawMin) * 0.18;
  const vMin   = rawMin - pad, vRange = (rawMax + pad) - vMin;

  const tx = i  => PAD.l + (i / (n - 1)) * iW;
  const ty = v  => PAD.t + (1 - (v - vMin) / vRange) * iH;

  const fmt = v => v.toFixed(1);

  const gridLines = [rawMin, rawMax].map(v =>
    `<line x1="${PAD.l}" y1="${ty(v).toFixed(1)}" x2="${PAD.l+iW}" y2="${ty(v).toFixed(1)}" stroke="#E2E8F0" stroke-width="0.8"/>` +
    `<text x="${PAD.l-3}" y="${(ty(v)+3).toFixed(1)}" font-size="7" fill="#94A3B8" text-anchor="end" font-family="Prompt,sans-serif">${fmt(v)}%</text>`
  ).join('');

  const fwdBand = pts.map((p,i) => `${tx(i).toFixed(1)},${ty(p.max).toFixed(1)}`).join(' ');
  const revBand = [...pts].reverse().map((p,i) => `${tx(n-1-i).toFixed(1)},${ty(p.min).toFixed(1)}`).join(' ');

  const areaD = `M ${tx(0).toFixed(1)},${ty(pts[0].min).toFixed(1)} ` +
    pts.slice(1).map((p,i) => `L ${tx(i+1).toFixed(1)},${ty(p.min).toFixed(1)}`).join(' ') +
    ` L ${tx(n-1).toFixed(1)},${(PAD.t+iH).toFixed(1)} L ${tx(0).toFixed(1)},${(PAD.t+iH).toFixed(1)} Z`;

  const minLine = pts.map((p,i) => `${tx(i).toFixed(1)},${ty(p.min).toFixed(1)}`).join(' ');

  const refLine = studentScore != null
    ? `<line x1="${PAD.l}" y1="${ty(studentScore).toFixed(1)}" x2="${PAD.l+iW}" y2="${ty(studentScore).toFixed(1)}" stroke="${color}" stroke-width="1.3" stroke-dasharray="3,2.5" opacity="0.75"/>` +
      `<text x="${PAD.l+iW+3}" y="${(ty(studentScore)+3.5).toFixed(1)}" font-size="7" fill="${color}" font-family="Prompt,sans-serif" font-weight="600">ฉัน</text>`
    : '';

  const dotsHtml = pts.map((p, i) => {
    const isLast = i === n - 1;
    const cx = tx(i).toFixed(1), cy = ty(p.min).toFixed(1);
    return `<circle cx="${cx}" cy="${cy}" r="${isLast ? 2.8 : 1.8}" fill="${isLast ? color : '#fff'}" stroke="${color}" stroke-width="1.5"/>` +
      (isLast ? `<text x="${cx}" y="${(ty(p.min)-5).toFixed(1)}" font-size="7.5" fill="${color}" text-anchor="middle" font-family="Prompt,sans-serif" font-weight="700">${fmt(p.min)}%</text>` : '');
  }).join('');

  const xLabels = pts.map((p, i) =>
    `<text x="${tx(i).toFixed(1)}" y="${H-2}" font-size="7.5" fill="#94A3B8" text-anchor="middle" font-family="Prompt,sans-serif">TCAS${p.year}</text>`
  ).join('');

  const uid = 'sp' + programId.replace(/[^a-z0-9]/gi, '');

  return `<svg viewBox="0 0 ${W} ${H}" width="100%" height="${H}" style="display:block;overflow:visible">
    <defs><linearGradient id="${uid}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0%" stop-color="${color}" stop-opacity="0.22"/>
      <stop offset="100%" stop-color="${color}" stop-opacity="0.01"/>
    </linearGradient></defs>
    ${gridLines}
    <polygon points="${fwdBand} ${revBand}" fill="${color}" opacity="0.1"/>
    <path d="${areaD}" fill="url(#${uid})"/>
    <polyline points="${minLine}" fill="none" stroke="${color}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/>
    ${refLine}${dotsHtml}${xLabels}
  </svg>`;
}
